(2776627, 387125, 56658, '<td valign="top">great job capturing the colors tones of the movie! the reaction looks more like a laugh than a scream to me though kinda ruins  what is a GREAT interpitation for me.</td>', 'great job capturing the colors tones of the movie! the reaction looks more like a laugh than a scream to me though kinda ruins  what is a GREAT interpitation for me.', '2006-08-30 22:19:30.000000', NULL, 1),
